mapper.select:
SELECT o.order_id AS orderId, o.status, o.ordered_at AS orderedAt, ( SELECT SUM(oi_total.price * oi_total.quantity) FROM order_items oi_total WHERE oi_total.order_id = o.order_id ) AS totalPrice, ( SELECT COUNT(*) FROM order_items oi_count WHERE oi_count.order_id = o.order_id ) AS itemCount, p.product_id AS mainProductId, p.name AS mainProductName, pi.image_url AS mainProductThumbnailImageUrl FROM orders o JOIN order_items oi ON oi.order_id = o.order_id AND oi.order_item_id = ( SELECT MIN(oi_first.order_item_id) FROM order_items oi_first WHERE oi_first.order_id = o.order_id ) JOIN products p ON p.product_id = oi.product_id LEFT JOIN product_images pi ON pi.product_id = p.product_id AND pi.is_thumbnail = true
o.member_id = #{memberId}
AND o.status = #{status}
AND o.order_id < #{lastOrderId}
ORDER BY o.order_id DESC LIMIT #{limit}
